// @generated by luaudocs. Do not edit; regenerated by every build.
//
// Inline code highlighting via a Pandoc-style language annotation:
//
//     `Flux.state(0)`{luau} renders through Shiki like a fenced code block.
//
// Reuses VitePress's own Shiki highlighter (captured via `markdown.shikiSetup`
// in the generated config) so no second Shiki instance is created and inline
// code shares the fenced examples' light/dark themes. Only `luau` and `lua`
// annotations are claimed here; any other `{...}` suffix (`{#id}`, `{.class}`,
// or an unknown language) is left for VitePress's `markdown-it-attrs` plugin.
//
// Every inline code span, highlighted or plain, also receives `v-pre`. VitePress
// compiles each markdown page as a Vue template and adds `v-pre` to fenced code
// blocks, but not inline code spans. Without `v-pre`, `{{` inside inline code
// is parsed as a Vue interpolation: `{{string}}` renders empty, and a nested
// Luau table type like `{{[string]: number}}` fails the build as an invalid Vue
// expression.
import type MarkdownIt from "markdown-it";
import type { Highlighter } from "shiki";

// VitePress's default light/dark theme pair for Shiki code blocks.
const THEMES = { light: "github-light", dark: "github-dark" } as const;

/** Languages supported for `{lang}` inline highlighting; `src/site.ts` preloads these in Shiki. */
export const LANGUAGES: readonly string[] = ["luau", "lua"];

/**
 * Pattern matching a `{...}` annotation suffix after an inline code span.
 * Shared with `src/markdown.ts` so `llms.txt` strips the same suffix shape.
 */
export const ANNOTATION_PATTERN = "\\{([\\w+#.-]+)\\}";

const ANNOTATION = new RegExp(`^${ANNOTATION_PATTERN}`);

export function inlineHighlightPlugin(
	md: MarkdownIt,
	getHighlighter: () => Highlighter | undefined,
): void {
	md.core.ruler.after("inline", "inline_highlight_annotate", (state) => {
		for (const block of state.tokens) {
			if (block.type !== "inline" || !block.children) continue;
			const children = block.children;
			for (let i = 0; i < children.length; i++) {
				const tok = children[i];
				if (!tok || tok.type !== "code_inline") continue;
				tok.attrSet("v-pre", "");
				const next = children[i + 1];
				if (!next || next.type !== "text") continue;
				const m = next.content.match(ANNOTATION);
				if (!m || !LANGUAGES.includes(m[1]!)) continue;
				tok.info = m[1]!;
				next.content = next.content.slice(m[0].length);
			}
		}
		return true;
	});

	const fallback =
		md.renderer.rules.code_inline ??
		((tokens, idx) => `<code v-pre>${md.utils.escapeHtml(tokens[idx]?.content ?? "")}</code>`);

	md.renderer.rules.code_inline = (tokens, idx, options, env, self) => {
		const tok = tokens[idx];
		if (!tok?.info) return fallback(tokens, idx, options, env, self);

		const hl = getHighlighter();
		if (!hl) return fallback(tokens, idx, options, env, self);
		const useLang = hl.getLoadedLanguages().includes(tok.info) ? tok.info : "text";

		try {
			const inner = hl.codeToHtml(tok.content, {
				lang: useLang,
				themes: THEMES,
				defaultColor: false,
				structure: "inline", // emit colored spans only, without <pre>/<code>/line wrappers
			});
			return `<code class="shiki-inline" v-pre>${inner}</code>`;
		} catch {
			return fallback(tokens, idx, options, env, self);
		}
	};
}
